(()=>{'use strict';const reduce=matchMedia('(prefers-reduced-motion: reduce)');let paused=reduce.matches;try{paused=paused||localStorage.getItem('chavi-motion')==='off'}catch{}const toggle=document.querySelector('.motion-toggle');const apply=()=>{document.body.classList.toggle('motion-off',paused);if(toggle){toggle.textContent=paused?'Motion: off ✳':'Motion: on ✳';toggle.setAttribute('aria-pressed',String(paused));}};apply();toggle?.addEventListener('click',()=>{paused=!paused;try{localStorage.setItem('chavi-motion',paused?'off':'on')}catch{}apply()});reduce.addEventListener('change',e=>{if(e.matches){paused=true;apply()}});const word=document.querySelector('#changing-word'),phrases=['made with personality.','fuelled by coffee.','sprinkled with a little play.','crafted with heart.'];let p=0,pos=phrases[0].length,deleting=false,delay=2100;function type(){if(!word)return;if(paused||document.hidden){setTimeout(type,500);return}let phrase=phrases[p];if(deleting){pos--;word.textContent=phrase.slice(0,pos);delay=38;if(pos===0){deleting=false;p=(p+1)%phrases.length;delay=250}}else{pos++;word.textContent=phrase.slice(0,pos);delay=75;if(pos>=phrase.length){deleting=true;delay=2200}}setTimeout(type,delay)}if(word)setTimeout(()=>{deleting=true;type()},2100);const photo=document.querySelector('.portrait-world'),mat=document.querySelector('.portrait-mat');if(photo&&mat){photo.addEventListener('pointermove',e=>{if(paused||e.pointerType!=='mouse')return;const r=photo.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;mat.style.transform=`rotate(${5+x*3}deg) rotateY(${x*8}deg) rotateX(${-y*6}deg)`});photo.addEventListener('pointerleave',()=>mat.style.transform='');}document.querySelectorAll('.love-sticker').forEach(button=>button.addEventListener('click',()=>{const r=button.getBoundingClientRect();if(paused){button.animate([{scale:1},{scale:1.05},{scale:1}],{duration:1});return}for(let i=0;i<7;i++){const heart=document.createElement('span');heart.className='love-pop';heart.textContent=i%2?'♡':'✧';heart.setAttribute('aria-hidden','true');heart.style.left=(r.left+r.width/2)+'px';heart.style.top=(r.top+15)+'px';heart.style.setProperty('--dx',`${(i-3)*24}px`);document.body.append(heart);setTimeout(()=>heart.remove(),950)}}));})();
(()=>{document.querySelectorAll('[data-note]').forEach(note=>note.addEventListener('click',()=>{const flipped=note.getAttribute('aria-pressed')==='true';note.setAttribute('aria-pressed',String(!flipped));note.querySelector('.note-face').hidden=!flipped;note.querySelector('.note-back').hidden=flipped;}));if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('in-view');observer.unobserve(entry.target)}})},{threshold:.08});document.querySelectorAll('[data-reveal]').forEach(el=>{el.classList.add('reveal-ready');observer.observe(el)});}})();
